<?php
declare(strict_types=1);
require __DIR__.'/app/bootstrap.php';
require_once __DIR__.'/app/Content.php';
header('Cache-Control: no-store');
header('X-Content-Type-Options: nosniff');
$remote=$_SERVER['REMOTE_ADDR']??'';
if (!in_array($remote,['127.0.0.1','::1','::ffff:127.0.0.1'],true)) {
    http_response_code(403);exit('Installation is local only. On the XAMPP computer, open http://localhost/sissy-fights-nxt/install.php.');
}
nxt_session();
$installed=is_file(__DIR__.'/app/config.php');$error='';$success=false;
$values=['db_host'=>'127.0.0.1','db_port'=>'3306','db_name'=>'sissy_fights_nxt','db_user'=>'root'];
$checks=['PHP 8.2 or newer'=>version_compare(PHP_VERSION,'8.2.0','>='),'PDO MySQL extension'=>extension_loaded('pdo_mysql'),'Writable app folder'=>is_writable(__DIR__.'/app'),'1,000 bot roster'=>is_file(__DIR__.'/data/bots.json'),'10,000 banter lines'=>is_file(__DIR__.'/data/banter.json')];
if (($_SERVER['REQUEST_METHOD']??'GET')==='POST' && !$installed) {
    $temp=null;$db=null;$guard=null;$committed=false;$preserveTemp=false;$schemaCreated=false;
    try {
        if (!hash_equals((string)$_SESSION['csrf'],(string)($_POST['csrf']??''))) throw new RuntimeException('The setup session changed. Reload this page.');
        if (in_array(false,$checks,true)) throw new RuntimeException('Complete all the checks below before installing.');
        foreach ($values as $key=>$default) $values[$key]=trim(is_string($_POST[$key]??null)?$_POST[$key]:$default);
        if (!preg_match('/\A[A-Za-z0-9_.:\-]{1,200}\z/',$values['db_host'])) throw new RuntimeException('Use a valid database host name or IP address.');
        if (!ctype_digit($values['db_port']) || (int)$values['db_port']<1 || (int)$values['db_port']>65535) throw new RuntimeException('Use a database port between 1 and 65535.');
        if (!preg_match('/\A[A-Za-z0-9_]{1,64}\z/',$values['db_name'])) throw new RuntimeException('The database name may contain only letters, numbers and underscores.');
        if ($values['db_user']==='' || strlen($values['db_user'])>128) throw new RuntimeException('Enter your MySQL username.');
        $password=is_string($_POST['db_pass']??null)?$_POST['db_pass']:'';
        if (strlen($password)>512) throw new RuntimeException('Database password is too long.');
        $guard=fopen(__DIR__.'/app/install.guard','c');
        if (!$guard || !flock($guard,LOCK_EX|LOCK_NB)) throw new RuntimeException('Setup is already running in another window.');
        if (is_file(__DIR__.'/app/config.php')) throw new RuntimeException('This installation is already configured.');
        $bots=json_decode((string)file_get_contents(__DIR__.'/data/bots.json'),true,512,JSON_THROW_ON_ERROR);
        $banter=json_decode((string)file_get_contents(__DIR__.'/data/banter.json'),true,512,JSON_THROW_ON_ERROR);
        if (!is_array($bots) || count($bots)!==1000 || !is_array($banter) || count($banter)!==10000 || count(array_unique($banter))!==10000) throw new RuntimeException('The bot roster or banter data is incomplete. Extract the full release again.');
        $seen=[];
        foreach ($bots as $bot) {
            if (!is_array($bot) || !is_string($bot['username']??null) || strlen($bot['username'])>32 || $bot['username']==='' || isset($seen[strtolower($bot['username'])])) throw new RuntimeException('The bot roster has a duplicate or invalid name.');
            $seen[strtolower($bot['username'])]=true;
        }
        $db=new PDO('mysql:host='.$values['db_host'].';port='.(int)$values['db_port'].';charset=utf8mb4',$values['db_user'],$password,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);
        $name=$values['db_name'];
        // Creation is optional: a pre-created empty database also works with a
        // restricted MySQL user that does not have global CREATE privileges.
        try {$db->exec('CREATE DATABASE IF NOT EXISTS `'.$name.'` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci');} catch (PDOException $ignored) {}
        $db->exec('USE `'.$name.'`');$db->exec("SET time_zone='+00:00'");
        $existing=$db->query('SHOW TABLES')->fetchAll();
        if ($existing) throw new RuntimeException('That database already contains tables. Choose a fresh empty database; setup never modifies another application or an existing playground.');
        foreach (explode(';',(string)file_get_contents(__DIR__.'/app/schema.sql')) as $sql) {
            if (trim($sql)==='') continue;
            $db->exec($sql);$schemaCreated=true;
        }
        $config=require __DIR__.'/app/config.example.php';
        foreach ($values as $k=>$v) $config[$k]=$k==='db_port'?(int)$v:$v;
        $config['db_pass']=$password;$config['app_secret']=bin2hex(random_bytes(32));
        $temp=__DIR__.'/app/config.pending-'.bin2hex(random_bytes(8)).'.php';
        if (file_put_contents($temp,"<?php\n// Generated by Sissy Fights NXT local installer.\nreturn ".var_export($config,true).";\n",LOCK_EX)===false) throw new RuntimeException('Could not write the configuration. Check app folder permissions.');
        @chmod($temp,0600);
        $db->beginTransaction();
        $insert=$db->prepare('INSERT INTO users(username,password_hash,is_bot,bot_number,personality,avatar,rating,created_at,last_seen) VALUES(?,NULL,1,?,?,?,1000,UTC_TIMESTAMP(),UTC_TIMESTAMP())');
        foreach ($bots as $i=>$bot) $insert->execute([$bot['username'],$i+1,substr((string)($bot['personality']??'scrapper'),0,24),GameContent::botAvatar($i+1)]);
        $db->prepare('INSERT INTO settings(name,value) VALUES(?,?) ON DUPLICATE KEY UPDATE value=VALUES(value)')->execute(['installed_at',gmdate('c')]);
        $db->prepare('INSERT INTO settings(name,value) VALUES(?,?) ON DUPLICATE KEY UPDATE value=VALUES(value)')->execute(['schema_version','1']);
        $db->prepare('INSERT INTO settings(name,value) VALUES(?,?) ON DUPLICATE KEY UPDATE value=VALUES(value)')->execute(['bot_roster_version',GameContent::BOT_ROSTER_VERSION]);
        $db->exec("INSERT INTO messages(room_id,user_id,body,created_at) VALUES(NULL,NULL,'Welcome to Sissy Fights NXT. Fresh grudges, same terrible manners.',UTC_TIMESTAMP())");
        $db->commit();$committed=true;
        if (!rename($temp,__DIR__.'/app/config.php')) {
            $preserveTemp=true;
            throw new RuntimeException('Players were installed, but config.php could not be activated. Rename the app/config.pending-*.php file to app/config.php, then reload. Do not run setup again.');
        }
        $temp=null;file_put_contents(__DIR__.'/app/install.lock',gmdate('c')."\n",LOCK_EX);$installed=true;$success=true;
    } catch (PDOException $e) {
        if ($db instanceof PDO && $db->inTransaction()) $db->rollBack();
        error_log('Sissy Fights NXT setup database failure: '.$e->getMessage());
        $error='Could not initialize MySQL. Start MySQL in XAMPP and check the host, port, username, password and database permissions. Detailed errors are in the PHP error log.';
        if ($schemaCreated && !$committed) $error.=' Setup left incomplete tables in the selected database. Choose another empty database when retrying; existing data is never deleted automatically.';
    } catch (Throwable $e) {
        if ($db instanceof PDO && $db->inTransaction()) $db->rollBack();
        $error=$e instanceof RuntimeException?$e->getMessage():'Setup data could not be read. Extract the full release again.';
        if ($schemaCreated && !$committed) $error.=' Setup left incomplete tables. Choose another empty database when retrying; existing data is never deleted automatically.';
    } finally {
        if ($temp && is_file($temp) && !$preserveTemp) @unlink($temp);
        if (is_resource($guard)) {flock($guard,LOCK_UN);fclose($guard);}
    }
}
function esc(string $s): string{return htmlspecialchars($s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
